DROP TABLE IF EXISTS `gameobject`;
CREATE TABLE `gameobject` (
  `guid` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Global Unique Identifier',
  `id` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Gameobject Identifier',
  `map` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'Map Identifier',
  `zoneId` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'Zone Identifier',
  `areaId` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'Area Identifier',
  `spawnMask` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `phaseMask` int(10) unsigned NOT NULL DEFAULT 1,
  `position_x` float NOT NULL DEFAULT 0,
  `position_y` float NOT NULL DEFAULT 0,
  `position_z` float NOT NULL DEFAULT 0,
  `orientation` float NOT NULL DEFAULT 0,
  `rotation0` float NOT NULL DEFAULT 0,
  `rotation1` float NOT NULL DEFAULT 0,
  `rotation2` float NOT NULL DEFAULT 0,
  `rotation3` float NOT NULL DEFAULT 0,
  `spawntimesecs` int(11) NOT NULL DEFAULT 0,
  `animprogress` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `state` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ScriptName` char(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `StringId` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `VerifiedBuild` int(11) DEFAULT NULL,
  `size` float NOT NULL DEFAULT -1,
  PRIMARY KEY (`guid`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=125303706 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Gameobject System';





















































































































































































































































